#!/usr/bin/env node
/**
 * Tests for hooks/mcp-readonly-guard.js. Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test tools/mcp-readonly-guard.test.mjs
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HOOK = join(dirname(fileURLToPath(import.meta.url)), '..', 'hooks', 'mcp-readonly-guard.js');
const SLACK = 'mcp__00000000-0000-0000-0000-000000000001__';
const M365 = 'mcp__00000000-0000-0000-0000-000000000002__';
const DOCS = 'mcp__00000000-0000-0000-0000-000000000003__';

const run = (input) => {
  const r = spawnSync(process.execPath, [HOOK], { input, encoding: 'utf8' });
  assert.equal(r.status, 0);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput : null;
};
const call = (tool_name, agent_type) =>
  run(JSON.stringify({ hook_event_name: 'PreToolUse', tool_name, tool_input: {}, ...(agent_type ? { agent_type } : {}) }));

test('given the worklog-scout agent, when it calls a connector tool that writes, then the guard denies it', () => {
  // Given
  const writes = [`${SLACK}slack_send_message`, `${SLACK}slack_add_reaction`, `${SLACK}slack_send_message_draft`,
    `${SLACK}slack_schedule_message`, `${M365}outlook_send_mail`, `${M365}outlook_create_reply_draft`,
    `${M365}outlook_batch_delete_messages`, `${M365}outlook_forward_mail`, `${M365}outlook_create_event`,
    `${M365}sharepoint_upload_file`, `${M365}outlook_modify_labels`, `${M365}outlook_respond_to_event`,
    'mcp__tracker__wit_update_work_item', 'mcp__tracker__pipelines_run_pipeline'];

  for (const tool of writes) {
    // When
    const d = call(tool, 'worklog-scout');

    // Then
    assert.equal(d?.permissionDecision, 'deny', tool);
    assert.match(d.permissionDecisionReason, /read-only agent \(worklog-scout\)/);
  }
});

test('given the worklog-scout agent, when a tool name holds no read verb, is camelCase or hyphenated, then the guard denies it', () => {
  // Given
  const tools = [`${DOCS}batch`, `${DOCS}replace`, 'mcp__browser__navigate', 'mcp__browser__computer',
    'mcp__browser__browser_exec', 'mcp__x__sendMessage', 'mcp__x__createIssue', 'mcp__x__notion-create-pages',
    'mcp__tracker__wit_work_item'];

  for (const tool of tools) {
    // When
    const d = call(tool, 'worklog-scout');

    // Then
    assert.equal(d?.permissionDecision, 'deny', tool);
  }
});

test('given the worklog-scout agent, when it calls a tool whose first verb reads, then the guard lets it through', () => {
  // Given
  const reads = [`${SLACK}slack_search_public_and_private`, `${SLACK}slack_read_thread`, `${SLACK}slack_read_user_profile`,
    `${M365}outlook_email_search`, `${M365}outlook_calendar_search`, `${M365}chat_message_search`,
    `${M365}teams_list_chats`, `${M365}get_me`, `${M365}read_resource`, `${M365}get_draft`,
    `${M365}outlook_get_schedule`, `${M365}list_archive_folders`, 'mcp__x__getMessages'];

  for (const tool of reads) {
    // When
    const d = call(tool, 'worklog-scout');

    // Then
    assert.equal(d, null, tool);
  }
});

test('given the main session, an agent that may write or a bad payload, when a write tool is called, then the guard makes no decision', () => {
  // Given
  const tool = `${SLACK}slack_send_message`;

  // When
  const decisions = [call(tool), call(tool, 'implementer'), call('Bash', 'worklog-scout'), run('not json')];

  // Then
  assert.deepEqual(decisions, [null, null, null, null]);
});
